mapper.select:
SELECT *
FROM nbpuask.conversation_shares
WHERE conversation_id=#{conversationId}
  AND owner_user_id=#{ownerUserId}
  AND share_available=TRUE
LIMIT 1

mapper.update:
UPDATE nbpuask.conversation_shares
SET share_available=FALSE
WHERE conversation_id=#{conversationId}
  AND owner_user_id=#{ownerUserId}

mapper.delete:
DELETE FROM nbpuask.conversation_shares
WHERE conversation_id=#{conversationId}
  AND owner_user_id=#{ownerUserId}

mapper.update:
UPDATE nbpuask.conversation_shares
SET visit_count=visit_count + 1,
    last_visited_time=#{lastVisitedTime}
WHERE share_id=#{shareId}
  AND share_available=TRUE
